import{_ as t,o,c as s,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Add your first source","description":"","frontmatter":{"title":"Add your first source"},"headers":[],"relativePath":"docs/getting-started/add-first-source.md","filePath":"docs/getting-started/add-first-source.md","lastUpdated":1794508483000}'),a={name:"docs/getting-started/add-first-source.md"};function n(d,e,i,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="add-your-first-source" tabindex="-1">Add your first source <a class="header-anchor" href="#add-your-first-source" aria-label="Permalink to &quot;Add your first source&quot;">​</a></h1><p>A <strong>source</strong> is a file or set of files added to a project: statements, exports or personal documents. Source projects hold the records; workbooks use those projects.</p><h2 id="add-files-to-a-project" tabindex="-1">Add files to a project <a class="header-anchor" href="#add-files-to-a-project" aria-label="Permalink to &quot;Add files to a project&quot;">​</a></h2><p>Open the project&#39;s <strong>+ Add</strong> or <strong>Add Source</strong> action. Choose files or a folder, or drag files into the dialog. Use the document type that matches the project; <strong>Auto Detect</strong> identifies supported formats when available.</p><p>Bank and card statements belong in <strong>Banking + Credit Cards</strong>; brokerage statements belong in <strong>Investment</strong>. Add retailer order histories to <strong>Retail Purchases</strong>, and other personal documents to <strong>General Documents</strong>.</p><p>Follow the import progress and review any file errors. Check the imported period, accounts and records before using the results. A listed file is not proof that every row was extracted successfully.</p><p>Ownership questions during statement import can be skipped. You can confirm account ownership later when setting up retirement planning.</p><h2 id="collect-statements-with-the-agent" tabindex="-1">Collect statements with the agent <a class="header-anchor" href="#collect-statements-with-the-agent" aria-label="Permalink to &quot;Collect statements with the agent&quot;">​</a></h2><p>The <a href="/docs/tools/statement-agents">Statement Download Agent</a> is another way to add files. You sign in yourself in the OrbySystems browser. For an unfamiliar statements page, demonstrate one download so OrbySystems can learn the steps locally.</p><h2 id="add-projects-to-a-workbook" tabindex="-1">Add projects to a workbook <a class="header-anchor" href="#add-projects-to-a-workbook" aria-label="Permalink to &quot;Add projects to a workbook&quot;">​</a></h2><p>A workbook&#39;s sources are projects, not statement files. Choose <strong>Add Sources</strong> in the workbook to select existing projects. Add later statements to those source projects; the workbook uses their updated records.</p><h2 id="manage-sources" tabindex="-1">Manage sources <a class="header-anchor" href="#manage-sources" aria-label="Permalink to &quot;Manage sources&quot;">​</a></h2><p>The <strong>Sources</strong> view lists imported sources and their status. Use its available actions to rescan after a parser fix, remove a source, or locate an original file when needed. OrbySystems keeps encrypted local copies of imported financial statements and exports; older imports with no stored copy may still need the original file.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Open <a href="/docs/getting-started/browse-recipes">Recipes</a> for charts and breakdowns, or <a href="/docs/getting-started/ask-questions">ask a question</a>.</p>',15)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
